import {ACOUSTIC_BANKS,ACOUSTIC_INSTRUMENTS} from './acoustic.js?v=0.13.0';
export function mountAcousticBrowser({panel,track,engine,toast}){
 const bank=ACOUSTIC_BANKS[track.type],def=ACOUSTIC_INSTRUMENTS[track.type],box=document.createElement('section');box.className='acoustic-player';
 box.innerHTML=`<div class="acoustic-head"><div><span>STUDIO / ENREGISTREMENTS STÉRÉO</span><h2>${def.name}</h2><p>${def.subtitle}</p></div><div class="acoustic-emblem" aria-hidden="true">${['piano','upright','epiano'].includes(track.type)?'♬':bank.loop?'𝄞':'♪'}</div></div><div class="acoustic-specs"><span>${bank.samples.length} enregistrements</span><span>${bank.layers} couche${bank.layers>1?'s':''} de vélocité</span><span>${(bank.bytes/1e6).toFixed(1)} Mo</span></div><div class="acoustic-load"><span id="acousticLoadStatus" role="status">Préparation des sons…</span><progress id="acousticProgress" max="${bank.samples.length}" value="0"></progress><button class="outline-btn" id="acousticRetry" hidden>Réessayer</button></div><div class="acoustic-actions"><button class="primary-btn" id="acousticAudition" disabled>▶ Écouter ce son</button><button class="outline-btn" id="acousticStop">■ Arrêter</button><a href="./samples/credits.html" target="_blank" rel="noopener">Sources & crédits</a></div><div class="acoustic-keyboard" aria-label="Clavier de préécoute">${Array.from({length:25},(_,i)=>60+i).map(n=>`<button data-acoustic-key="${n}" class="${[1,3,6,8,10].includes(n%12)?'black':''}" aria-label="Jouer la note MIDI ${n}">${n%12===0?'C'+(n/12-1):''}</button>`).join('')}</div>`;
 panel.querySelector('.plugin-window-params').before(box);const status=box.querySelector('#acousticLoadStatus'),progress=box.querySelector('progress'),audition=box.querySelector('#acousticAudition'),retry=box.querySelector('#acousticRetry');
 const load=async()=>{retry.hidden=true;try{await engine.prepareInstrument(track.type,(done,total)=>{if(!box.isConnected)return;status.textContent=done===total?'Prêt à jouer':'Chargement des sons… '+done+' / '+total;progress.value=done;});if(box.isConnected)audition.disabled=false;}catch(error){if(box.isConnected){status.textContent=error.message;retry.hidden=false;}}};
 retry.onclick=load;audition.onclick=()=>engine.previewPreset(track.type,track.instrument).catch(e=>toast(e.message));box.querySelector('#acousticStop').onclick=()=>engine.stopPreview();for(const key of box.querySelectorAll('[data-acoustic-key]'))key.onclick=()=>engine.preview(track.type,Number(key.dataset.acousticKey),track.id);load();
}
